func TestRandomHistoriesAreConsistent(t *testing.T) {
	priv, pub := testKeys(3)
	m := single("A", "B", "C")
	tl := NewTimeline(ConfigChange{Index: 0, Membership: m})
	vr := NewVerifier(pub)
	rng := rand.New(rand.NewSource(42))

	for iter := 0; iter < 500; iter++ {
		n := 1 + rng.Intn(10)
		qcs := make([]QC, 0, n)
		local := make([]LogEntry, 0, n)
		for i := 0; i < n; i++ {
			epoch := uint32(rng.Intn(6))
			val := fmt.Sprintf("v%d", i) // unique per index => no conflicts
			qcs = append(qcs, mkQC(t, priv, uint64(i), epoch, val, "A", "B"))
			if rng.Intn(4) != 0 {
				local = append(local, LogEntry{Index: uint64(i), Epoch: epoch, Value: val})
			}
		}
		a := Analyze(qcs, local, 0, tl, vr)
		if !a.Linearizable {
			t.Fatalf("iter %d: unique values must never conflict", iter)
		}
		for k, c := range a.Committed {
			if c.Index != uint64(k) {
				t.Fatalf("iter %d: prefix hole committed[%d].Index=%d", iter, k, c.Index)
			}
		}
		if a.HasCommit && a.RepairStart != a.CommitEnd+1 {
			t.Fatalf("iter %d: repair start %d != commit end+1 %d", iter, a.RepairStart, a.CommitEnd+1)
		}
	}
}
